import { Check, Copy } from 'lucide-react';
import { useEffect, useState, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { TreeList } from '../tree-list/TreeList';
import type { TreeNode } from '../tree-list/tree-model';
import { entries, joinPath, jsonType, matchAncestors, pathsToDepth } from './json-model';
import { jsonTypeClass, jsonViewerVariants } from './json-viewer.variants';

export interface JsonViewerLabels {
  copyPath: string;
  copyValue: string;
  copied: string;
  copyFailed: string;
  /** Toolbar hint before a node is selected. */
  selectHint: string;
  /** Summary of an object / array. */
  keys: (n: number) => string;
  items: (n: number) => string;
  /** Name of the root when the path is empty. */
  root: string;
}

const DEFAULT_LABELS: JsonViewerLabels = {
  copyPath: 'Copy path',
  copyValue: 'Copy value',
  copied: 'Copied to clipboard',
  copyFailed: 'Copy failed',
  selectHint: 'Select a node to copy its path or value',
  keys: (n) => `${n} ${n === 1 ? 'key' : 'keys'}`,
  items: (n) => `${n} ${n === 1 ? 'item' : 'items'}`,
  root: '(root)',
};

export interface JsonViewerProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Any JSON-serialisable value. */
  data: unknown;
  /** Accessible name of the tree. */
  label?: string;
  /** Levels expanded on first render (default 1). */
  defaultExpandDepth?: number;
  /** Deeper containers render as a summary and do not expand. */
  maxDepth?: number;
  /** Highlights matching keys and values and expands their ancestors. */
  search?: string;
  /** Shows the path / copy toolbar (default true). */
  toolbar?: boolean;
  /** Max height of the scrollable body (px or CSS length). */
  maxHeight?: number | string;
  /** Built-in strings (English defaults). */
  labels?: Partial<JsonViewerLabels>;
}

const s = jsonViewerVariants();

function highlight(text: string, query: string): ReactNode {
  const q = query.trim().toLowerCase();
  if (!q) return text;
  const out: ReactNode[] = [];
  let from = 0;
  let at = text.toLowerCase().indexOf(q);
  while (at !== -1) {
    if (at > from) out.push(text.slice(from, at));
    out.push(
      <mark key={at} className={s.mark()}>
        {text.slice(at, at + q.length)}
      </mark>,
    );
    from = at + q.length;
    at = text.toLowerCase().indexOf(q, from);
  }
  if (from < text.length) out.push(text.slice(from));
  return out;
}

function preview(value: unknown, labels: JsonViewerLabels, query: string): ReactNode {
  const type = jsonType(value);
  if (type === 'object' || type === 'array') {
    const n = entries(value).length;
    return <span className={jsonTypeClass.summary}>{type === 'array' ? `[ ] ${labels.items(n)}` : `{ } ${labels.keys(n)}`}</span>;
  }
  const text = type === 'string' ? JSON.stringify(value) : String(value ?? null);
  return <span className={jsonTypeClass[type]}>{highlight(text, query)}</span>;
}

/**
 * Collapsible JSON inspector on TreeList (tree keyboard pattern): objects and arrays expand,
 * values are coloured by type with contrast-safe text tokens, `search` highlights and reveals
 * matches, and the toolbar copies the selected node's path or value.
 */
export function JsonViewer({
  data,
  label = 'JSON',
  defaultExpandDepth = 1,
  maxDepth = Infinity,
  search = '',
  toolbar = true,
  maxHeight,
  labels: labelsProp,
  className,
  ref,
}: JsonViewerProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp };
  const [expanded, setExpanded] = useState(() => pathsToDepth(data, Math.min(defaultExpandDepth, maxDepth)));
  const [selected, setSelected] = useState<string[]>([]);
  const [status, setStatus] = useState<'idle' | 'copied' | 'failed'>('idle');
  const [revealed, setRevealed] = useState({ search: '', data: undefined as unknown });

  // Reveal matches when the query (or data) changes; the user can still collapse them afterwards.
  if (revealed.search !== search || revealed.data !== data) {
    setRevealed({ search, data });
    const extra = [...matchAncestors(data, search, maxDepth)].filter((p) => !expanded.includes(p));
    if (extra.length) setExpanded([...expanded, ...extra]);
  }

  const values = new Map<string, unknown>([['', data]]);
  const build = (value: unknown, path: string, level: number): TreeNode[] =>
    entries(value).map(([key, v]) => {
      const id = joinPath(path, key);
      values.set(id, v);
      const type = jsonType(v);
      const keyText = String(key);
      return {
        id,
        label: keyText,
        content: (
          <span className={s.row()}>
            <span className={typeof key === 'number' ? jsonTypeClass.punctuation : jsonTypeClass.key}>{highlight(keyText, search)}</span>
            <span className={jsonTypeClass.punctuation}>: </span>
            {preview(v, labels, search)}
          </span>
        ),
        children: (type === 'object' || type === 'array') && level < maxDepth ? build(v, id, level + 1) : undefined,
      };
    });
  const rootType = jsonType(data);
  const nodes: TreeNode[] =
    rootType === 'object' || rootType === 'array'
      ? build(data, '', 1)
      : [{ id: '', label: labels.root, content: <span className={s.row()}>{preview(data, labels, search)}</span> }];

  useEffect(() => {
    if (status === 'idle') return;
    const id = window.setTimeout(() => setStatus('idle'), 2000);
    return () => window.clearTimeout(id);
  }, [status]);

  const current = selected[0];
  const copy = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setStatus('copied');
    } catch {
      setStatus('failed');
    }
  };

  return (
    <div ref={ref} className={cn(s.root(), className)}>
      {toolbar && (
        <div className={s.toolbar()}>
          <span className={s.path()}>{current !== undefined ? <span className={s.pathValue()}>{current || labels.root}</span> : labels.selectHint}</span>
          <button type="button" disabled={current === undefined} onClick={() => current !== undefined && copy(current)} className={s.action()}>
            <Copy size={13} aria-hidden />
            {labels.copyPath}
          </button>
          <button
            type="button"
            disabled={current === undefined}
            onClick={() => current !== undefined && copy(JSON.stringify(values.get(current), null, 2) ?? 'null')}
            className={s.action()}
          >
            {status === 'copied' ? <Check size={13} aria-hidden /> : <Copy size={13} aria-hidden />}
            {labels.copyValue}
          </button>
          <span role="status" className="sr-only">
            {status === 'copied' ? labels.copied : status === 'failed' ? labels.copyFailed : ''}
          </span>
        </div>
      )}
      <div className={s.body()} style={maxHeight !== undefined ? { maxHeight } : undefined}>
        <TreeList aria-label={label} nodes={nodes} expanded={expanded} onExpandedChange={setExpanded} selected={selected} onSelectedChange={setSelected} indent={14} />
      </div>
    </div>
  );
}

export { JsonViewer, type JsonViewerProps, type JsonViewerLabels } from './JsonViewer';
export { joinPath, jsonType, matchAncestors, type JsonValue, type JsonType } from './json-model';
export { jsonViewerVariants, jsonTypeClass, type JsonViewerVariantProps } from './json-viewer.variants';
export { doc as jsonViewerDoc } from './JsonViewer.doc';

export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

export type JsonType = 'string' | 'number' | 'boolean' | 'null' | 'object' | 'array';

export function jsonType(value: unknown): JsonType {
  if (value === null || value === undefined) return 'null';
  if (Array.isArray(value)) return 'array';
  const t = typeof value;
  return t === 'string' || t === 'number' || t === 'boolean' ? t : 'object';
}

/** Child entries of an object or array (`[]` for primitives). */
export function entries(value: unknown): Array<[key: string | number, value: unknown]> {
  if (Array.isArray(value)) return value.map((v, i) => [i, v]);
  if (value && typeof value === 'object') return Object.entries(value);
  return [];
}

const IDENT = /^[A-Za-z_$][\w$]*$/;

/** Appends a key to a path: `users[0].name`, `meta["content-type"]`. */
export function joinPath(parent: string, key: string | number) {
  if (typeof key === 'number') return `${parent}[${key}]`;
  if (IDENT.test(key)) return parent ? `${parent}.${key}` : key;
  return `${parent}[${JSON.stringify(key)}]`;
}

/** Paths of every container whose subtree contains a key or primitive value matching `query`. */
export function matchAncestors(data: unknown, query: string, maxDepth = Infinity) {
  const q = query.trim().toLowerCase();
  const out = new Set<string>();
  if (!q) return out;
  const walk = (value: unknown, path: string, depth: number, ancestors: string[]) => {
    for (const [k, v] of entries(value)) {
      const p = joinPath(path, k);
      const type = jsonType(v);
      const primitive = type !== 'object' && type !== 'array';
      if (String(k).toLowerCase().includes(q) || (primitive && String(v).toLowerCase().includes(q))) ancestors.forEach((a) => out.add(a));
      if (!primitive && depth < maxDepth) walk(v, p, depth + 1, [...ancestors, p]);
    }
  };
  walk(data, '', 1, []);
  return out;
}

/** Container paths up to (not including) `depth` levels, for the initial expansion. */
export function pathsToDepth(data: unknown, depth: number) {
  const out: string[] = [];
  const walk = (value: unknown, path: string, level: number) => {
    if (level > depth) return;
    for (const [k, v] of entries(value)) {
      const p = joinPath(path, k);
      const t = jsonType(v);
      if (t === 'object' || t === 'array') {
        if (level < depth) out.push(p);
        walk(v, p, level + 1);
      }
    }
  };
  walk(data, '', 0);
  return out;
}

import { tv, type VariantProps } from '../../utils/tv';

/** Value colours: contrast-safe text tokens only (same mapping as CodeBlock's JSON tokens). */
export const jsonTypeClass = {
  key: 'text-primary-text',
  string: 'text-warning-text',
  number: 'text-destructive-text',
  boolean: 'font-semibold text-foreground',
  null: 'italic text-muted-foreground',
  summary: 'text-muted-foreground',
  punctuation: 'text-muted-foreground',
} as const;

export const jsonViewerVariants = tv({
  slots: {
    root: 'overflow-hidden rounded-md border border-border bg-card text-start',
    toolbar: 'flex min-h-10 items-center gap-2 border-b border-border bg-secondary/40 ps-3 pe-1.5',
    path: 'min-w-0 flex-1 truncate font-mono text-[11.5px] text-muted-foreground',
    pathValue: 'text-foreground',
    action: [
      'inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 rounded-md px-2 font-mono text-[11px] text-muted-foreground transition-colors motion-reduce:transition-none',
      'hover:bg-secondary hover:text-foreground disabled:pointer-events-none disabled:opacity-50',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    ],
    body: 'overflow-auto p-1.5 font-mono text-[12.5px]',
    row: 'min-w-0 truncate whitespace-pre',
    mark: 'rounded-[3px] bg-warning/16 text-warning-chip-text',
    empty: 'px-3 py-6 text-center font-sans text-[12.5px] text-muted-foreground',
  },
});

export type JsonViewerVariantProps = VariantProps<typeof jsonViewerVariants>;

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
